# Words of Plainness - Anthem Player Deployment
# Run: cd C:\Users\aaron\Documents\words-of-plainness
#       powershell -ExecutionPolicy Bypass -File .\deploy-anthem.ps1

$ErrorActionPreference = "Stop"

if (-not (Test-Path ".eleventy.js")) {
    Write-Host "ERROR: Run this from the repo root." -ForegroundColor Red
    exit 1
}

Write-Host ""
Write-Host "=== Words of Plainness - Anthem Player Deployment ===" -ForegroundColor Yellow
Write-Host ""

function Write-B64File($b64, $outPath) {
    $dir = Split-Path $outPath -Parent
    if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllBytes($outPath, [Convert]::FromBase64String($b64))
}

# 1. Backup index.njk
$indexPath = Join-Path "src" "index.njk"
if (-not (Test-Path $indexPath)) {
    Write-Host "ERROR: src/index.njk not found." -ForegroundColor Red
    exit 1
}
Copy-Item $indexPath (Join-Path "src" "index.njk.bak") -Force
Write-Host 'Backed up index.njk' -ForegroundColor Green

# 2. Write anthem-player.css
$cssB64 = ''
Write-B64File $cssB64 (Join-Path "src" "css" "anthem-player.css")
Write-Host 'Written: src/css/anthem-player.css' -ForegroundColor Green

# 3. Write anthem-player.js
$jsB64 = ''
Write-B64File $jsB64 (Join-Path "src" "js" "anthem-player.js")
Write-Host 'Written: src/js/anthem-player.js' -ForegroundColor Green

# 4. Write base.njk
$baseB64 = ''
Write-B64File $baseB64 (Join-Path "src" "_includes" "layouts" "base.njk")
Write-Host 'Written: src/_includes/layouts/base.njk' -ForegroundColor Green

# 5. Insert anthem block into index.njk
$anthemB64 = ''
$anthemHtml = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($anthemB64))

$indexFull = (Resolve-Path $indexPath).Path
$indexContent = [System.IO.File]::ReadAllText($indexFull)

if ($indexContent -match "anthem-block") {
    Write-Host 'SKIP: already contains anthem' -ForegroundColor Cyan
} else {
    $anchor = '<p class="hero-text">'
    if ($indexContent.Contains($anchor)) {
        $indexContent = $indexContent.Replace($anchor, $anthemHtml + "        " + $anchor)
        [System.IO.File]::WriteAllText($indexFull, $indexContent)
        Write-Host 'Anthem block inserted into index.njk' -ForegroundColor Green
    } else {
        Write-Host 'WARNING: anchor not found in index.njk' -ForegroundColor Yellow
    }
}

# 6. Create audio directory
$audioDir = Join-Path "src" "assets" "audio"
if (-not (Test-Path $audioDir)) {
    New-Item -ItemType Directory -Path $audioDir -Force | Out-Null
}
Write-Host 'Audio directory ready' -ForegroundColor Green

Write-Host ""
Write-Host "=== DEPLOYMENT COMPLETE ===" -ForegroundColor Green
Write-Host ""
Write-Host "ONE MANUAL STEP: Copy your anthem MP3 to:" -ForegroundColor Yellow
Write-Host '  src/assets/audio/the-marks-of-your-worth.mp3' -ForegroundColor Cyan
Write-Host ""
Write-Host "Then test or deploy:" -ForegroundColor White
Write-Host '  npx @11ty/eleventy --serve' -ForegroundColor Cyan
Write-Host '  git add -A && git commit -m "feat: anthem player" && git push' -ForegroundColor Cyan
Write-Host ""
